export interface Chuong2ExamAttempt {
  examId: string;
  examCode: string;
  score: number;
  totalQuestions: number;
  correctCount: number;
  durationSeconds: number;
  date: string;
  userAnswers?: Record<string | number, any>;
}

export interface Chuong2UserProgress {
  completedLessons: string[];
  examScores: Record<string, { score: number; date: string; attempts: number }>;
  savedNotes: Record<string, string>;
  totalXP: number;
  lastActiveDate: string;
  rankTitle: string;
}

const STORAGE_PREFIX = "hoa12_c2_";

export function getChuong2UserProgress(): Chuong2UserProgress {
  try {
    const raw = localStorage.getItem(`${STORAGE_PREFIX}progress`);
    if (raw) return JSON.parse(raw);
  } catch (e) {}
  return {
    completedLessons: [],
    examScores: {},
    savedNotes: {},
    totalXP: 0,
    lastActiveDate: new Date().toISOString(),
    rankTitle: "Tân Binh Hóa Học"
  };
}

export function calculateChuong2ExamScore(questionsInput: any, userAnswers: Record<string | number, any>) {
  const questions: Chuong2Question[] = Array.isArray(questionsInput) ? questionsInput : (questionsInput?.questions || []);
  let p1Correct = 0;
  let p1Score = 0;
  let p2Score = 0;
  let p3Correct = 0;
  let p3Score = 0;
  const detail: Record<string | number, any> = {};

  questions.forEach(q => {
    const qKey = q.id || q.number;
    const ans = userAnswers[qKey];

    if (q.part === 1) {
      const correctOpt = q.options?.find(o => o.isCorrect)?.letter || q.correctAnswer;
      const isCorrect = (ans === correctOpt);
      if (isCorrect) {
        p1Correct++;
        p1Score += (q.points || 0.25);
      }
      detail[qKey] = { isCorrect, userAns: ans, correctAns: correctOpt };
    } else if (q.part === 2) {
      const subAns = ans || {};
      let correctSubCount = 0;
      const subDetail: Record<string, boolean> = {};

      q.options?.forEach(opt => {
        const letter = opt.letter;
        const subVal = subAns[letter] !== undefined ? subAns[letter] : (subAns[letter.toLowerCase()] !== undefined ? subAns[letter.toLowerCase()] : subAns[letter.toUpperCase()]);
        const isCorrectSub = (subVal === opt.isCorrect);
        subDetail[letter] = isCorrectSub;
        if (isCorrectSub) correctSubCount++;
      });

      let questionP2Score = 0;
      if (correctSubCount === 1) questionP2Score = 0.1;
      else if (correctSubCount === 2) questionP2Score = 0.25;
      else if (correctSubCount === 3) questionP2Score = 0.5;
      else if (correctSubCount === 4) questionP2Score = 1.0;

      p2Score += questionP2Score;
      detail[qKey] = { subDetail, correctSubCount, points: questionP2Score };
    } else if (q.part === 3) {
      const userVal = String(ans || "").trim().replace(/,/g, ".");
      const expected = String(q.correctAnswer || "").trim().replace(/,/g, ".");
      const isCorrect = userVal !== "" && (userVal === expected || Math.abs(parseFloat(userVal) - parseFloat(expected)) < 0.05);
      if (isCorrect) {
        p3Correct++;
        p3Score += (q.points || 0.25);
      }
      detail[qKey] = { isCorrect, userAns: userVal, correctAns: expected };
    }
  });

  p1Score = Math.round(p1Score * 100) / 100;
  p2Score = Math.round(p2Score * 100) / 100;
  p3Score = Math.round(p3Score * 100) / 100;
  const totalScore = Math.round((p1Score + p2Score + p3Score) * 10) / 10;

  return {
    totalScore,
    score10: Math.min(10.0, totalScore),
    p1Score,
    p2Score,
    p3Score,
    part1Score: p1Score,
    part2Score: p2Score,
    part3Score: p3Score,
    p1Correct,
    p3Correct,
    detail
  };
}

export function getChuong2ExamHistory(): Chuong2ExamAttempt[] {
  try {
    const raw = localStorage.getItem(`${STORAGE_PREFIX}exam_history`);
    const list: Chuong2ExamAttempt[] = raw ? JSON.parse(raw) : [];
    if (list.length === 0) {
      return [
        {
          examId: "c2_de_021",
          examCode: "021",
          score: 9.5,
          totalQuestions: 28,
          correctCount: 26,
          durationSeconds: 2280,
          date: new Date(Date.now() - 86400000).toISOString()
        }
      ];
    }
    return list;
  } catch (e) {
    return [];
  }
}

export function saveChuong2ExamAttempt(attempt: Chuong2ExamAttempt) {
  try {
    const raw = localStorage.getItem(`${STORAGE_PREFIX}exam_history`);
    const list: Chuong2ExamAttempt[] = raw ? JSON.parse(raw) : [];
    list.unshift(attempt);
    if (list.length > 100) list.length = 100;
    localStorage.setItem(`${STORAGE_PREFIX}exam_history`, JSON.stringify(list));
  } catch (e) {}

  try {
    const p = getChuong2UserProgress();
    const prev = p.examScores[attempt.examId] || { score: 0, date: "", attempts: 0 };
    p.examScores[attempt.examId] = {
      score: Math.max(prev.score, attempt.score),
      date: attempt.date,
      attempts: prev.attempts + 1
    };
    p.totalXP += Math.round(attempt.score * 20);
    p.rankTitle = getChuong2RankTitle(p.totalXP);
    localStorage.setItem(`${STORAGE_PREFIX}progress`, JSON.stringify(p));
  } catch (e) {}
}

export function saveChuong2ExamResult(examId: string, score: number, durationSeconds: number = 0) {
  try {
    const p = getChuong2UserProgress();
    const prev = p.examScores[examId] || { score: 0, date: "", attempts: 0 };
    p.examScores[examId] = {
      score: Math.max(prev.score, score),
      date: new Date().toISOString(),
      attempts: prev.attempts + 1
    };
    p.totalXP += Math.round(score * 20);
    p.rankTitle = getChuong2RankTitle(p.totalXP);
    localStorage.setItem(`${STORAGE_PREFIX}progress`, JSON.stringify(p));
  } catch (e) {}
}

export function shuffleChuong2Exam(exam: Chuong2Exam): Chuong2Exam {
  if (!exam || !exam.questions) return exam;

  const clonedQuestions: Chuong2Question[] = JSON.parse(JSON.stringify(exam.questions));
  const p1 = clonedQuestions.filter(q => q.part === 1);
  const p2 = clonedQuestions.filter(q => q.part === 2);
  const p3 = clonedQuestions.filter(q => q.part === 3);

  const shuffleArray = <T>(arr: T[]): T[] => {
    const res = [...arr];
    for (let i = res.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [res[i], res[j]] = [res[j], res[i]];
    }
    return res;
  };

  const shuffledP1 = shuffleArray(p1).map(q => {
    if (q.options && q.options.length > 0) {
      const origCorrectOpt = q.options.find(o => o.isCorrect) || q.options.find(o => o.letter === q.correctAnswer);
      const origCorrectText = origCorrectOpt?.text;
      const shuffledOptions = shuffleArray(q.options);
      const letters = ["A", "B", "C", "D"];
      shuffledOptions.forEach((opt, idx) => {
        opt.letter = letters[idx];
      });
      const newCorrectOpt = shuffledOptions.find(o => (origCorrectText && o.text === origCorrectText) || o.isCorrect);
      const newCorrectLetter = newCorrectOpt?.letter || "A";
      shuffledOptions.forEach(opt => {
        opt.isCorrect = (opt.letter === newCorrectLetter);
      });
      return {
        ...q,
        options: shuffledOptions,
        correctAnswer: newCorrectLetter
      };
    }
    return q;
  });

  const shuffledP2 = shuffleArray(p2).map(q => {
    if (q.options && q.options.length > 0) {
      const shuffledOptions = shuffleArray(q.options);
      const letters = ["a", "b", "c", "d"];
      shuffledOptions.forEach((opt, idx) => {
        opt.letter = letters[idx];
      });
      return {
        ...q,
        options: shuffledOptions
      };
    }
    return q;
  });

  const shuffledP3 = shuffleArray(p3);

  const finalQuestions = [...shuffledP1, ...shuffledP2, ...shuffledP3].map((q, idx) => ({
    ...q,
    displayNumber: idx + 1
  }));

  return {
    ...exam,
    questions: finalQuestions
  };
}

export function getChuong2RankTitle(xp: number): string {
  if (xp >= 5000) return "👑 Thủ Khoa Hóa 12";
  if (xp >= 3000) return "🍇 Bậc Thầy Carbohydrate";
  if (xp >= 1500) return "🌾 Chuyên Gia Tinh Bột & Đường";
  if (xp >= 500) return "🥇 Cao Thủ Glucose & Fructose";
  return "🥉 Tân Binh Hóa Học";
}
